/* Host harness for LLP (49.1, ; doc/dev/protocols/llp.md).
 *
 * Three parts:
 *
 * 1. The shared vectors (llp_vectors.txt, generated by the Python reference in
 *    host/llp): the serial binding's exact bytes, receiver counters for good
 *    and damaged streams, and scenarios -- two links driven step by step, every
 *    emitted frame, event and delivery compared with what Python produced.
 *    This is the "two implementations agree" check.
 * 2. Fuzz: random and mutated bytes into the serial receiver and the link, in
 *    every state, under ASan/UBSan.
 * 3. Soak: two links over a simulated serial line with a byte rate, byte
 *    corruption and loss, and a total outage; both sides send data. Checked:
 *    every delivered frame is intact, in order and never duplicated, the
 *    receiver's buffer never overflows (credits are right), traffic flows,
 *    and the link recovers from the outage by itself.
 *
 * Usage: llp_host [iterations [seed]]; LLP_VECTORS overrides the vector path. */
#include "kernel/llp.h"
#include "shim.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static int fails;
#define CHECK(c, ...) do { if (!(c)) { fails++; printf("FAIL %s:%d: ", __func__, __LINE__); \
    printf(__VA_ARGS__); printf("\n"); if (fails > 40) exit(1); } } while (0)

/* --- small helpers ------------------------------------------------------------ */

static int unhex(const char *s, uint8_t *out, uint32_t cap) {
    if (strcmp(s, "-") == 0) return 0;
    uint32_t n = (uint32_t)strlen(s);
    if (n % 2 || n / 2 > cap) return -1;
    for (uint32_t i = 0; i < n / 2; i++) {
        unsigned v;
        if (sscanf(s + 2 * i, "%2x", &v) != 1) return -1;
        out[i] = (uint8_t)v;
    }
    return (int)(n / 2);
}

static void tohex(const uint8_t *p, uint32_t n, char *out) {
    static const char h[] = "0123456789abcdef";
    for (uint32_t i = 0; i < n; i++) { out[2 * i] = h[p[i] >> 4]; out[2 * i + 1] = h[p[i] & 15]; }
    out[2 * n] = 0;
}

static void pattern(uint8_t *p, uint32_t n, uint32_t start) {
    for (uint32_t i = start; i < n; i++) p[i] = (uint8_t)(i + n);
}

/* What a scenario's `send` carries (host/llp vectors.data_payload()). */
static void data_payload(uint8_t type, uint8_t *p, uint32_t n) {
    if (type == LLP_T_P9) {
        p[0] = (uint8_t)n; p[1] = (uint8_t)(n >> 8); p[2] = (uint8_t)(n >> 16); p[3] = (uint8_t)(n >> 24);
        pattern(p, n, 4);
    } else {
        pattern(p, n, 0);
    }
}

#define WIRE_CAP (LLP_SERIAL_WIRE_MAX(LLP_MAX_PAYLOAD) + 16)
#define RXBUF_CAP (LLP_HDR_LEN + LLP_MAX_PAYLOAD + LLP_CRC_LEN)

/* --- 1a. frame and rx vectors ------------------------------------------------- */

static uint8_t g_a[2 * WIRE_CAP], g_b[2 * WIRE_CAP], g_c[2 * WIRE_CAP];
static uint8_t g_emit[2 * WIRE_CAP];
static uint32_t g_emit_len;
static void emit_put(void *ctx, uint8_t b) { (void)ctx; if (g_emit_len < sizeof g_emit) g_emit[g_emit_len++] = b; }

static void vec_frame(char *rest) {
    char name[64], pay[2 * WIRE_CAP], wire[4 * WIRE_CAP];
    int type, seq;
    if (sscanf(rest, "%63s %d %d %s %s", name, &type, &seq, pay, wire) != 5) { CHECK(0, "bad frame line"); return; }
    int pn = unhex(pay, g_a, sizeof g_a), wn = unhex(wire, g_b, sizeof g_b);
    CHECK(pn >= 0 && wn > 0, "%s: hex", name);
    uint8_t hdr[LLP_HDR_LEN];
    llp_hdr_put(hdr, (uint8_t)type, (uint8_t)seq, (uint16_t)pn);
    int n = llp_serial_encode(hdr, g_a, (uint16_t)pn, g_c, sizeof g_c);
    CHECK(n == wn && memcmp(g_c, g_b, (size_t)wn) == 0, "%s: encode differs (%d vs %d bytes)", name, n, wn);
    g_emit_len = 0;
    llp_serial_emit(hdr, g_a, (uint16_t)pn, emit_put, NULL);
    CHECK(g_emit_len == (uint32_t)wn && memcmp(g_emit, g_b, (size_t)wn) == 0, "%s: emit differs from encode", name);

    static uint8_t rb[RXBUF_CAP];
    llp_serial_rx_t rx;
    llp_serial_rx_init(&rx, rb, sizeof rb);
    llp_frame_t f;
    int got = 0;
    for (int i = 0; i < wn; i++) {
        if (llp_serial_feed(&rx, g_b[i], &f)) {
            got++;
            CHECK(f.type == type && f.seq == seq && f.len == pn && memcmp(f.payload, g_a, (size_t)pn) == 0,
                  "%s: decode differs", name);
        }
    }
    CHECK(got == 1, "%s: %d frames decoded", name, got);
}

static void vec_rx(char *rest) {
    char name[64], wire[8 * WIRE_CAP];
    unsigned cap, frames, crc, runt, badlen, ovf;
    if (sscanf(rest, "%63s %u %s %u %u %u %u %u", name, &cap, wire, &frames, &crc, &runt, &badlen, &ovf) != 8) {
        CHECK(0, "bad rx line");
        return;
    }
    static uint8_t stream[4 * WIRE_CAP];
    int n = unhex(wire, stream, sizeof stream);
    uint8_t *buf = malloc(cap);
    llp_serial_rx_t rx;
    llp_serial_rx_init(&rx, buf, cap);
    llp_frame_t f;
    for (int i = 0; i < n; i++) (void)llp_serial_feed(&rx, stream[i], &f);
    CHECK(rx.frames == frames && rx.crc_err == crc && rx.runt == runt && rx.bad_len == badlen && rx.overflow == ovf,
          "%s: frames %u crc %u runt %u bad_len %u overflow %u, want %u %u %u %u %u", name,
          rx.frames, rx.crc_err, rx.runt, rx.bad_len, rx.overflow, frames, crc, runt, badlen, ovf);
    free(buf);
}

/* --- 1b. scenarios ------------------------------------------------------------- */

#define OUTBOX_MAX 64
typedef struct {
    char        name;
    llp_link_t  link;
    bool        live;
    uint8_t     out[OUTBOX_MAX][LLP_HDR_LEN + LLP_MAX_PAYLOAD + 2];
    uint32_t    out_len[OUTBOX_MAX];
    int         nout;
    uint32_t    ring, cap;
} side_t;

static side_t g_side[2];
static char **g_log;
static int g_nlog, g_caplog;

static void logf_(const char *fmt, ...) __attribute__((format(printf, 1, 2)));
#include <stdarg.h>
static void logf_(const char *fmt, ...) {
    char tmp[2 * (LLP_HDR_LEN + LLP_MAX_PAYLOAD) + 64];
    va_list ap;
    va_start(ap, fmt);
    vsnprintf(tmp, sizeof tmp, fmt, ap);
    va_end(ap);
    if (g_nlog == g_caplog) {
        g_caplog = g_caplog ? 2 * g_caplog : 64;
        g_log = realloc(g_log, (size_t)g_caplog * sizeof *g_log);
    }
    g_log[g_nlog++] = strdup(tmp);
}

static void log_clear(void) {
    for (int i = 0; i < g_nlog; i++) free(g_log[i]);
    g_nlog = 0;
}

static int sc_send(void *ctx, const uint8_t hdr[LLP_HDR_LEN], const uint8_t *payload, uint16_t len) {
    side_t *s = ctx;
    if (s->nout == OUTBOX_MAX) return -1;
    uint8_t *b = s->out[s->nout];
    memcpy(b, hdr, LLP_HDR_LEN);
    memcpy(b + LLP_HDR_LEN, payload, len);
    s->out_len[s->nout++] = LLP_HDR_LEN + len;
    static char hex[2 * (LLP_HDR_LEN + LLP_MAX_PAYLOAD) + 1];
    tohex(b, LLP_HDR_LEN + len, hex);
    logf_("emit %c %s", s->name, hex);
    return 0;
}

static uint32_t sc_free(void *ctx) { side_t *s = ctx; return s->cap - s->ring; }

static const char *ev_name(llp_event_t ev) {
    switch (ev) {
        case LLP_EV_UP: return "up";
        case LLP_EV_DOWN: return "down";
        case LLP_EV_MISMATCH: return "mismatch";
        case LLP_EV_PEER_STATE: return "peer_state";
    }
    return "?";
}

static void sc_event(void *ctx, llp_event_t ev, const llp_link_t *l) {
    (void)l;
    side_t *s = ctx;
    logf_("event %c %s", s->name, ev_name(ev));
}

static side_t *side(const char *n) { return &g_side[n[0] == 'B']; }
static side_t *other(side_t *s) { return s == &g_side[0] ? &g_side[1] : &g_side[0]; }

static uint32_t g_now;

static void sc_step(const char *step) {
    char verb[16], a[8];
    int n = 0;
    if (sscanf(step, "%15s %7s%n", verb, a, &n) < 1) return;
    const char *rest = step + n;
    if (strcmp(verb, "time") == 0) { g_now = (uint32_t)strtoul(a, NULL, 10); return; }
    side_t *s = side(a);

    if (strcmp(verb, "init") == 0) {
        unsigned role, window, maxp, major;
        char sess[16], mac[16];
        sscanf(rest, "%u %15s %u %u %u %15s", &role, sess, &window, &maxp, &major, mac);
        llp_config_t cfg = {0};
        cfg.role = (uint8_t)role;
        cfg.major = (uint8_t)major;
        cfg.minor = 0;
        cfg.max_payload = (uint16_t)maxp;
        cfg.rx_window = (uint8_t)window;
        unhex(mac, cfg.mac, 6);
        cfg.send = sc_send;
        cfg.rx_free = sc_free;
        cfg.event = sc_event;
        cfg.ctx = s;
        s->nout = 0;
        s->ring = 0;
        s->cap = window ? window : 64;
        s->live = true;
        llp_link_init(&s->link, &cfg, (uint32_t)strtoul(sess, NULL, 16), g_now);
    } else if (strcmp(verb, "tick") == 0) {
        llp_link_tick(&s->link, g_now);
    } else if (strcmp(verb, "deliver") == 0 || strcmp(verb, "repeat") == 0) {
        /* repeat: deliver but keep the frames, so they arrive again later. */
        bool keep = (verb[0] == 'r');
        side_t *d = other(s);
        int k = s->nout;
        static uint8_t buf[OUTBOX_MAX][LLP_HDR_LEN + LLP_MAX_PAYLOAD + 2];
        static uint32_t lens[OUTBOX_MAX];
        memcpy(buf, s->out, sizeof buf);
        memcpy(lens, s->out_len, sizeof lens);
        if (!keep) s->nout = 0;
        for (int i = 0; i < k; i++) {
            llp_frame_t f, out;
            if (llp_frame_parse(buf[i], lens[i], &f) != 0) { CHECK(0, "own frame unparseable"); continue; }
            if (llp_link_input(&d->link, &f, g_now, &out)) {
                if (d->ring < d->cap) { d->ring++; logf_("recv %c %u %u", d->name, out.type, out.len); }
                else logf_("full %c", d->name);
            }
        }
    } else if (strcmp(verb, "drop") == 0) {
        s->nout = 0;
    } else if (strcmp(verb, "send") == 0) {
        unsigned type, len;
        sscanf(rest, "%u %u", &type, &len);
        static uint8_t p[8192];
        data_payload((uint8_t)type, p, len);
        int rc = llp_link_send(&s->link, (uint8_t)type, p, (uint16_t)len, g_now);
        logf_("result %c %d", s->name, rc);
    } else if (strcmp(verb, "consume") == 0) {
        unsigned k;
        sscanf(rest, "%u", &k);
        s->ring = s->ring > k ? s->ring - k : 0;
    } else if (strcmp(verb, "state") == 0) {
        int up, rssi;
        sscanf(rest, "%d %d", &up, &rssi);
        llp_link_send_state(&s->link, (uint8_t)up, (int8_t)rssi, g_now);
    } else {
        CHECK(0, "unknown step %s", verb);
    }
}

/* Runs the vector file. Returns the number of scenarios replayed. */
static int run_vectors(const char *path, int *nframes, int *nrx) {
    FILE *fp = fopen(path, "r");
    if (!fp) { printf("cannot open %s (set LLP_VECTORS)\n", path); exit(1); }
    static char line[1 << 16];
    int scenarios = 0;
    char sc_name[64] = "";
    char cur_step[256] = "";
    char **expect = NULL;
    int nexp = 0, capexp = 0;
    bool in_sc = false;

#define FLUSH_STEP() do { \
        if (cur_step[0]) { \
            bool same = (nexp == g_nlog); \
            for (int i = 0; same && i < nexp; i++) same = strcmp(expect[i], g_log[i]) == 0; \
            CHECK(same, "scenario %s, step '%s': C produced %d lines, Python %d%s%s%s%s", sc_name, cur_step, \
                  g_nlog, nexp, g_nlog ? "\n   C first: " : "", g_nlog ? g_log[0] : "", \
                  nexp ? "\n   Py first: " : "", nexp ? expect[0] : ""); \
            if (!same) for (int i = 0; i < (nexp > g_nlog ? nexp : g_nlog); i++) { \
                const char *x = i < nexp ? expect[i] : "-", *y = i < g_nlog ? g_log[i] : "-"; \
                if (strcmp(x, y)) { printf("   line %d\n     py: %.120s\n     c:  %.120s\n", i, x, y); break; } } \
        } \
        for (int i = 0; i < nexp; i++) free(expect[i]); \
        nexp = 0; log_clear(); cur_step[0] = 0; } while (0)

    while (fgets(line, sizeof line, fp)) {
        line[strcspn(line, "\n")] = 0;
        if (!line[0] || line[0] == '#') continue;
        if (line[0] == ' ') {
            if (nexp == capexp) { capexp = capexp ? 2 * capexp : 32; expect = realloc(expect, (size_t)capexp * sizeof *expect); }
            expect[nexp++] = strdup(line + 2);
            continue;
        }
        FLUSH_STEP();
        if (strncmp(line, "frame ", 6) == 0) { vec_frame(line + 6); (*nframes)++; }
        else if (strncmp(line, "rx ", 3) == 0) { vec_rx(line + 3); (*nrx)++; }
        else if (strncmp(line, "scenario ", 9) == 0) {
            snprintf(sc_name, sizeof sc_name, "%s", line + 9);
            memset(g_side, 0, sizeof g_side);
            g_side[0].name = 'A';
            g_side[1].name = 'B';
            g_now = 0;
            in_sc = true;
        } else if (strcmp(line, "end") == 0) {
            in_sc = false;
            scenarios++;
        } else if (strncmp(line, "step ", 5) == 0 && in_sc) {
            snprintf(cur_step, sizeof cur_step, "%s", line + 5);
            sc_step(line + 5);
        } else {
            CHECK(0, "unrecognised vector line: %.60s", line);
        }
    }
    FLUSH_STEP();
    free(expect);
    fclose(fp);
    return scenarios;
}

/* --- 2. fuzz ------------------------------------------------------------------ */

static int fz_send(void *ctx, const uint8_t hdr[LLP_HDR_LEN], const uint8_t *payload, uint16_t len) {
    (void)ctx; (void)hdr; (void)payload; (void)len;
    return 0;
}
static uint32_t fz_free(void *ctx) { return *(uint32_t *)ctx; }

static void fuzz(int iterations, uint64_t *rs) {
    static uint8_t rb[RXBUF_CAP], stream[3 * WIRE_CAP];
    for (int it = 0; it < iterations; it++) {
        uint32_t freeslots = host_rand(rs) % 9;
        llp_config_t cfg = { .role = LLP_ROLE_HOST, .max_payload = (uint16_t)(1514 + host_rand(rs) % 3000),
                             .rx_window = (uint8_t)(host_rand(rs) % 70), .send = fz_send, .rx_free = fz_free,
                             .ctx = &freeslots };
        llp_link_t l;
        uint32_t now = host_rand(rs);
        llp_link_init(&l, &cfg, host_rand(rs) | 1u, now);

        /* Half the time, bring the link up first with a well-formed peer HELLO. */
        if (host_rand(rs) & 1) {
            uint8_t p[LLP_HELLO_LEN] = { LLP_OP_HELLO, 1, 0, LLP_ROLE_RADIO, (uint8_t)(host_rand(rs) & 3) };
            uint32_t ps = host_rand(rs) | 1u;
            memcpy(&p[5], &ps, 4);
            memcpy(&p[9], &l.session, 4);
            p[13] = 0xea; p[14] = 0x05; p[15] = (uint8_t)(host_rand(rs) % 80);
            llp_frame_t f = { LLP_T_LINK, 0, LLP_HELLO_LEN, p }, out;
            (void)llp_link_input(&l, &f, now, &out);
        }

        /* A stream of frames: valid shapes with random fields, then bytes
         * mutated on the wire, through the serial receiver into the link. */
        uint32_t sn = 0;
        int nframes = 1 + (int)(host_rand(rs) % 8);
        for (int k = 0; k < nframes && sn < sizeof stream - WIRE_CAP; k++) {
            static uint8_t pay[LLP_MAX_PAYLOAD + 8];
            uint16_t len = (uint16_t)(host_rand(rs) % 4 == 0 ? host_rand(rs) % (LLP_MAX_PAYLOAD + 8) : host_rand(rs) % 40);
            for (uint32_t i = 0; i < len; i++) pay[i] = (uint8_t)host_rand(rs);
            uint8_t type = (uint8_t)(host_rand(rs) % 5);
            if (type == LLP_T_LINK && len) pay[0] = (uint8_t)(1 + host_rand(rs) % 5);
            if (type == LLP_T_P9 && len >= 4 && (host_rand(rs) & 1)) memcpy(pay, &(uint32_t){len}, 4);
            uint8_t hdr[LLP_HDR_LEN];
            llp_hdr_put(hdr, type, (uint8_t)host_rand(rs), len);
            int w = llp_serial_encode(hdr, pay, len, stream + sn, sizeof stream - sn);
            if (w > 0) sn += (uint32_t)w;
        }
        int muts = (int)(host_rand(rs) % 4);
        for (int m = 0; m < muts && sn; m++) stream[host_rand(rs) % sn] ^= (uint8_t)(1u << (host_rand(rs) % 8));
        if (host_rand(rs) % 8 == 0) for (uint32_t i = 0; i < sn; i++) stream[i] = (uint8_t)host_rand(rs);

        llp_serial_rx_t rx;
        uint32_t cap = (host_rand(rs) & 1) ? sizeof rb : 8 + host_rand(rs) % 64;
        llp_serial_rx_init(&rx, rb, cap);
        for (uint32_t i = 0; i < sn; i++) {
            llp_frame_t f, out;
            if (llp_serial_feed(&rx, stream[i], &f)) {
                now += host_rand(rs) % 50;
                if (llp_link_input(&l, &f, now, &out)) {
                    CHECK(out.len <= cfg.max_payload, "delivered more than max_payload");
                    volatile uint8_t sink = 0;
                    for (uint32_t j = 0; j < out.len; j++) sink ^= out.payload[j];   /* ASan: in bounds */
                    (void)sink;
                }
            }
            if (host_rand(rs) % 64 == 0) { now += host_rand(rs) % 4000; llp_link_tick(&l, now); }
        }
        static uint8_t pay[LLP_MAX_PAYLOAD];
        (void)llp_link_send(&l, LLP_T_ETH, pay, (uint16_t)(host_rand(rs) % 2000), now);
        llp_link_tick(&l, now + 5000);
    }
}

/* --- 3. soak ------------------------------------------------------------------ */

#define LINE_CAP (256 * 1024)
#define RING_MAX 64

typedef struct {
    llp_link_t      link;
    llp_serial_rx_t rx;
    uint8_t         rxbuf[RXBUF_CAP];
    uint8_t         line[LINE_CAP];       /* bytes on their way to the other side */
    uint32_t        lhead, ltail;
    uint32_t        ring, cap;            /* the application's receive buffer */
    uint32_t        next_tx_id;           /* counter carried in each sent frame */
    uint32_t        last_rx_id;           /* highest counter received */
    bool            any_rx;
    uint32_t        delivered, ring_full, ups, downs;
    uint8_t         type;
} peer_t;

static peer_t g_p[2];

static int sk_send(void *ctx, const uint8_t hdr[LLP_HDR_LEN], const uint8_t *payload, uint16_t len) {
    peer_t *p = ctx;
    static uint8_t w[WIRE_CAP];
    int n = llp_serial_encode(hdr, payload, len, w, sizeof w);
    if (n < 0) return -1;
    if (LINE_CAP - (p->lhead - p->ltail) < (uint32_t)n) return -1;   /* the UART's FIFO is full */
    for (int i = 0; i < n; i++) p->line[(p->lhead++) % LINE_CAP] = w[i];
    return 0;
}
static uint32_t sk_free(void *ctx) { peer_t *p = ctx; return p->cap - p->ring; }
static void sk_event(void *ctx, llp_event_t ev, const llp_link_t *l) {
    (void)l;
    peer_t *p = ctx;
    if (ev == LLP_EV_UP) p->ups++;
    if (ev == LLP_EV_DOWN) p->downs++;
}

/* A data frame: id[4], then bytes derived from the id. P9 frames carry the
 * size[4] first. */
static uint16_t make_data(uint8_t type, uint32_t id, uint8_t *buf, uint64_t *rs) {
    uint16_t len = (uint16_t)(24 + host_rand(rs) % 1490);
    uint32_t o = 0;
    if (type == LLP_T_P9) { memcpy(buf, &(uint32_t){len}, 4); o = 4; }
    memcpy(buf + o, &id, 4);
    for (uint32_t i = o + 4; i < len; i++) buf[i] = (uint8_t)(id * 31u + i);
    return len;
}

static bool check_data(const llp_frame_t *f, uint32_t *id) {
    uint32_t o = (f->type == LLP_T_P9) ? 4u : 0u;
    if (f->len < o + 4) return false;
    memcpy(id, f->payload + o, 4);
    for (uint32_t i = o + 4; i < f->len; i++)
        if (f->payload[i] != (uint8_t)(*id * 31u + i)) return false;
    return true;
}

typedef struct { uint32_t ms; uint32_t bytes_per_ms; uint32_t flip_ppm, drop_ppm; bool outage; } phase_t;

static void soak(uint64_t *rs, int scale, uint32_t *total_delivered, uint32_t *total_lost) {
    memset(g_p, 0, sizeof g_p);
    for (int i = 0; i < 2; i++) {
        peer_t *p = &g_p[i];
        p->cap = 8;
        p->type = i ? LLP_T_P9 : LLP_T_ETH;
        llp_serial_rx_init(&p->rx, p->rxbuf, sizeof p->rxbuf);
        llp_config_t cfg = { .role = (uint8_t)(i ? LLP_ROLE_RADIO : LLP_ROLE_HOST), .max_payload = 1514,
                             .rx_window = 8, .send = sk_send, .rx_free = sk_free, .event = sk_event, .ctx = p };
        llp_link_init(&p->link, &cfg, 0x1000u + (uint32_t)i * 0x777u, 0);
    }
    /* 300 bytes/ms is 3 Mbit/s of UART. */
    const phase_t phases[] = {
        { 2000u * (uint32_t)scale, 300, 0, 0, false },          /* clean */
        { 4000u * (uint32_t)scale, 300, 20, 5, false },        /* noisy: bit flips and lost bytes */
        { 5000, 300, 0, 0, true },                              /* outage: nothing gets through */
        { 3000u * (uint32_t)scale, 300, 5, 1, false },         /* back */
    };
    uint32_t now = 0;
    uint32_t delivered_before[2] = {0, 0};
    for (unsigned ph = 0; ph < sizeof phases / sizeof phases[0]; ph++) {
        const phase_t *P = &phases[ph];
        uint32_t lost_before = g_p[0].link.st.rx_lost + g_p[1].link.st.rx_lost;
        for (uint32_t t = 0; t < P->ms; t++, now++) {
            for (int i = 0; i < 2; i++) {
                peer_t *src = &g_p[i], *dst = &g_p[1 - i];
                /* The wire: up to bytes_per_ms move, damaged at the given rates. */
                for (uint32_t b = 0; b < P->bytes_per_ms && src->ltail != src->lhead; b++) {
                    uint8_t c = src->line[(src->ltail++) % LINE_CAP];
                    if (P->outage) continue;
                    if (P->drop_ppm && host_rand(rs) % 1000000u < P->drop_ppm) continue;
                    if (P->flip_ppm && host_rand(rs) % 1000000u < P->flip_ppm) c ^= (uint8_t)(1u << (host_rand(rs) % 8));
                    llp_frame_t f, out;
                    if (!llp_serial_feed(&dst->rx, c, &f)) continue;
                    if (!llp_link_input(&dst->link, &f, now, &out)) continue;
                    if (dst->ring >= dst->cap) { dst->ring_full++; continue; }
                    dst->ring++;
                    uint32_t id;
                    CHECK(out.type == src->type, "phase %u: wrong type", ph);
                    CHECK(check_data(&out, &id), "phase %u: damaged payload delivered", ph);
                    if (dst->any_rx) {
                        CHECK(id > dst->last_rx_id, "phase %u: id %u after %u (dup/reorder)", ph, id, dst->last_rx_id);
                        if (ph == 0) CHECK(id == dst->last_rx_id + 1, "phase 0: id %u after %u (gap on a clean line)", id, dst->last_rx_id);
                    } else if (ph == 0) {
                        CHECK(id == 0, "phase 0: first id %u", id);
                    }
                    dst->last_rx_id = id;
                    dst->any_rx = true;
                    dst->delivered++;
                }
            }
            for (int i = 0; i < 2; i++) {
                peer_t *p = &g_p[i];
                /* The application drains its buffer at a random rate... */
                uint32_t k = host_rand(rs) % 3;
                p->ring = p->ring > k ? p->ring - k : 0;
                /* ...and offers data whenever the link will take it. */
                static uint8_t buf[LLP_MAX_PAYLOAD];
                for (int n = 0; n < 2 && llp_link_can_send(&p->link); n++) {
                    uint16_t len = make_data(p->type, p->next_tx_id, buf, rs);
                    if (llp_link_send(&p->link, p->type, buf, len, now) == 0) p->next_tx_id++;
                }
                if (!llp_link_can_send(&p->link) && p->link.state == LLP_UP) {
                    /* Note the attempt, so the link probes if it stays blocked. */
                    uint16_t len = make_data(p->type, p->next_tx_id, buf, rs);
                    if (llp_link_send(&p->link, p->type, buf, len, now) == 0) p->next_tx_id++;
                }
                llp_link_tick(&p->link, now);
            }
        }
        uint32_t d0 = g_p[0].delivered + g_p[1].delivered;
        if (ph == 2) {
            CHECK(g_p[0].downs >= 1 && g_p[1].downs >= 1, "outage: links did not notice (%u/%u downs)",
                  g_p[0].downs, g_p[1].downs);
        } else {
            CHECK(g_p[0].link.state == LLP_UP && g_p[1].link.state == LLP_UP, "phase %u: link not up at the end", ph);
            CHECK(g_p[0].delivered > delivered_before[0] + 50 && g_p[1].delivered > delivered_before[1] + 50,
                  "phase %u: too little traffic (%u, %u)", ph, g_p[0].delivered - delivered_before[0],
                  g_p[1].delivered - delivered_before[1]);
        }
        if (ph == 0)
            CHECK(g_p[0].link.st.rx_lost + g_p[1].link.st.rx_lost == lost_before, "clean phase lost frames");
        delivered_before[0] = g_p[0].delivered;
        delivered_before[1] = g_p[1].delivered;
        (void)d0;
    }
    CHECK(g_p[0].ring_full == 0 && g_p[1].ring_full == 0, "receive buffer overflowed (%u/%u): credits are wrong",
          g_p[0].ring_full, g_p[1].ring_full);
    CHECK(g_p[0].ups >= 2 && g_p[1].ups >= 2, "did not come back up after the outage");
    *total_delivered += g_p[0].delivered + g_p[1].delivered;
    *total_lost += g_p[0].link.st.rx_lost + g_p[1].link.st.rx_lost;
}

/* --- main ---------------------------------------------------------------------- */

int main(int argc, char **argv) {
    int iterations = argc > 1 ? atoi(argv[1]) : 2000;
    uint64_t seed = argc > 2 ? strtoull(argv[2], NULL, 0) : 0x40c0ffeeULL;
    uint64_t rs = seed ? seed : 1;
    const char *path = getenv("LLP_VECTORS") ? getenv("LLP_VECTORS") : "llp_vectors.txt";

    int nframes = 0, nrx = 0;
    int nsc = run_vectors(path, &nframes, &nrx);
    CHECK(nsc >= 11 && nframes >= 9 && nrx >= 8, "vector file looks truncated (%d scenarios)", nsc);

    fuzz(iterations, &rs);

    uint32_t delivered = 0, lost = 0;
    int soaks = iterations >= 1000 ? 3 : 1;
    for (int i = 0; i < soaks; i++) soak(&rs, 1, &delivered, &lost);

    if (fails) { printf("llp_host: %d failures (seed %llu)\n", fails, (unsigned long long)seed); return 1; }
    printf("llp_host: %d frame + %d rx vectors and %d scenarios agree with host/llp; %d fuzzed streams "
           "(seed %llu); %d soak(s), %u frames delivered, %u lost to line noise, no overflow, no fault\n",
           nframes, nrx, nsc, iterations, (unsigned long long)seed, soaks, delivered, lost);
    return 0;
}
